Think: Extract time-like tokens from temp_workspace/server_work.log, validate and normalize them to HH:MM (24-hour), write one clean timestamp per line to temp_workspace/timestamps.txt, and write any lines that contain malformed time entries to temp_workspace/timestamps_errors.log. I'll use a single awk command that scans each line for occurrences of H:MM or HH:MM, normalizes valid ones, and logs malformed lines.

Act: bash

```bash
awk 'BEGIN{t="temp_workspace/timestamps.txt"; e="temp_workspace/timestamps_errors.log"; print "" > t; print "" > e}
{
  s=$0; pos=1; malformed_line=0;
  while (match(substr(s,pos), "[0-9]{1,2}:[0-9]{1,2}")) {
    m=substr(s,pos+RSTART-1, RLENGTH);
    split(m, a, ":");
    h = a[1]+0; mn = a[2]+0;
    if (h>=0 && h<=23 && mn>=0 && mn<=59) {
      printf "%02d:%02d\n", h, mn >> t;
    } else {
      if (!malformed_line) { print $0 >> e; malformed_line=1 }
    }
    pos += RSTART + RLENGTH - 1;
  }
}' temp_workspace/server_work.log
```

