Think: Process each path from temp_workspace/file_list.csv: for each path, try to read and count lines with awk, append "full_path,line_count" to per_file_line_counts.csv, and log read errors to errors.log.

Act: bash

```bash
awk -F '\t' '{
 path=$1;
 # attempt to read first line to detect empty file vs error vs content
 c = getline line < path;
 if (c == -1) {
   print path " : cannot read" >> "temp_workspace/errors.log";
 } else {
   if (c == 0) {
     count = 0;
   } else {
     count = 1;
     while ((getline line < path) > 0) count++;
   }
   close(path);
   print path "," count >> "temp_workspace/per_file_line_counts.csv";
 }
}' temp_workspace/file_list.csv
