Think: Create verification_summary.json by consolidating target_path.txt, recursive_listing.txt, and candidates.txt into JSON with target_path, recursive_listing array, and candidates array (each candidate an object with path and type).

Act: bash

```bash
awk '
FNR==NR { tp=$0; next }
FILENAME=="recursive_listing.txt" { rl[++rln]=$0; next }
FILENAME=="candidates.txt" { cl[++cln]=$0; next }
END {
  print "{"
  printf "  \"target_path\": \"%s\",\n", tp
  printf "  \"recursive_listing\": [\n"
  for(i=1;i<=rln;i++){
    line=rl[i];
    gsub(/\\/,"\\\\",line); gsub(/"/,"\\\"",line);
    printf "    \"%s\"%s\n", line, (i<rln?",":"")
  }
  print "  ],"
  printf "  \"candidates\": [\n"
  for(i=1;i<=cln;i++){
    line=cl[i];
    n=split(line,a," ");
    type=a[n];
    path=a[1];
    for(j=2;j<n;j++) path=path " " a[j];
    gsub(/\\/,"\\\\",path); gsub(/"/,"\\\"",path);
    gsub(/\\/,"\\\\",type); gsub(/"/,"\\\"",type);
    printf "    {\"path\": \"%s\", \"type\": \"%s\"}%s\n", path, type, (i<cln?",":"")
  }
  print "  ]"
  print "}"
}
' target_path.txt recursive_listing.txt candidates.txt > verification_summary.json
